import json
import unittest

from documents.ai.classification import NonRetryableRequestFailure, RetryableRequestFailure
from documents.ai.extraction import (
    ExtractionFailure,
    ExtractionOutputValidationError,
    FIELD_DEFINITIONS,
    build_extraction_text_format,
