:root {
  --color-bg: #f4f5f7;
  --color-surface: #ffffff;
  --color-border: #dfe3e8;
  --color-text: #1f2933;
  --color-muted: #5c6773;
  --color-link: #1d4ed8;
  --color-accepted: #1f9d55;
  --color-uncertain: #b45309;
  --color-failed: #c0392b;
  --color-processing: #52606d;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
}

.page {
  max-width: 900px;
  margin: 0 auto;
  padding: 16px;
}

nav.site-nav {
  display: flex;
  gap: 16px;
  align-items: center;
  padding: 12px 0;
  margin-bottom: 16px;
  border-bottom: 1px solid var(--color-border);
}

nav.site-nav a {
  color: var(--color-link);
  text-decoration: none;
  font-weight: 600;
}

nav.site-nav a:hover {
  text-decoration: underline;
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 12px;
  word-break: break-word;
}

h2 {
  font-size: 1.15rem;
  margin: 24px 0 8px;
}

p.lede {
  color: var(--color-muted);
}

.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 20px;
}

.field {
  margin-bottom: 16px;
}

.field label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
}

.field .help-text {
  color: var(--color-muted);
  font-size: 0.85rem;
  margin-top: 4px;
}

.field .errorlist {
  color: var(--color-failed);
  list-style: none;
  padding: 0;
  margin: 4px 0 0;
  font-size: 0.9rem;
}

input[type="file"] {
  display: block;
  width: 100%;
  padding: 8px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  background: var(--color-bg);
}

input[type="file"]::file-selector-button {
  padding: 6px 12px;
  margin-right: 12px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  background: var(--color-surface);
  cursor: pointer;
}

button[type="submit"] {
  padding: 10px 20px;
  border: none;
  border-radius: 6px;
  background: var(--color-link);
  color: #fff;
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
}

button[type="submit"]:disabled {
  background: var(--color-muted);
  cursor: progress;
}

#upload-status {
  margin-top: 12px;
  color: var(--color-muted);
  font-size: 0.9rem;
}

.badge {
  display: inline-block;
  padding: 3px 12px;
  border-radius: 999px;
  color: #fff;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.badge-accepted { background: var(--color-accepted); }
.badge-uncertain { background: var(--color-uncertain); }
.badge-failed { background: var(--color-failed); }
.badge-processing { background: var(--color-processing); }

.table-wrapper {
  overflow-x: auto;
  border: 1px solid var(--color-border);
  border-radius: 8px;
}

table {
  width: 100%;
  border-collapse: collapse;
  background: var(--color-surface);
  font-size: 0.95rem;
}

th, td {
  text-align: left;
  padding: 10px 12px;
  border-bottom: 1px solid var(--color-border);
  vertical-align: top;
}

thead th {
  background: var(--color-bg);
  font-weight: 700;
}

tbody tr:last-child td {
  border-bottom: none;
}

.note {
  color: var(--color-muted);
  font-size: 0.9rem;
}

.warning-row td {
  color: var(--color-uncertain);
  font-weight: 600;
}

@media (max-width: 640px) {
  .page {
    padding: 12px;
  }

  nav.site-nav {
    gap: 12px;
  }

  h1 {
    font-size: 1.25rem;
  }

  .card {
    padding: 14px;
  }

  th, td {
    padding: 8px;
    font-size: 0.85rem;
  }
}

