{% extends "documents/base.html" %}

{% block title %}Upload document{% endblock %}

{% block content %}
  <h1>Upload a PDF for classification</h1>
  <p class="lede">
    Accepted classes: INVOICE, BOL, POD, OTHER. At most 10 pages and 10,000,000 bytes.
    Both text-layer and scanned PDFs are supported: scanned pages go through local
    OCR, and when the text classification cannot accept a result, one visual
    fallback reviews the original page images. A document that cannot be classified
    with sufficient evidence ends as uncertain rather than a guess.
  </p>
  <div class="card">
    <form method="post" enctype="multipart/form-data" id="upload-form">
      {% csrf_token %}
      {{ form.non_field_errors }}
      <div class="field">
        {{ form.document.label_tag }}
        {{ form.document }}
        {% if form.document.help_text %}
          <p class="help-text">{{ form.document.help_text }}</p>
        {% endif %}
        {{ form.document.errors }}
      </div>
      <button type="submit" id="upload-submit">Upload</button>
      <p id="upload-status" hidden>
        Processing&hellip; OCR and AI analysis can take up to a minute or two,
        especially for scanned documents.
      </p>
    </form>
  </div>
  <script>
    document.getElementById("upload-form").addEventListener("submit", function (event) {
      var button = document.getElementById("upload-submit");
      if (button.disabled) {
        event.preventDefault();
        return;
      }
      button.disabled = true;
      button.textContent = "Processing…";
      document.getElementById("upload-status").hidden = false;
    });
  </script>
{% endblock %}

