{% extends "documents/base.html" %}

{% block title %}Result — {{ attempt.original_name }}{% endblock %}

{% block content %}
  <h1>{{ attempt.original_name }}</h1>
  <p>
    Status:
    <span class="badge badge-{{ attempt.status|lower }}">{{ attempt.get_status_display }}</span>
  </p>

  <div class="card">
    {% if attempt.fallback_observations %}
      <p class="note">
        The primary text/OCR classification was not accepted, so a visual fallback reviewed
        the original PDF's page images once.
        {% if attempt.status == "ACCEPTED" %}The accepted label below comes from that fallback.{% endif %}
      </p>
    {% endif %}

    {% if attempt.status == "ACCEPTED" %}
      <p>Accepted label: <strong>{{ attempt.get_accepted_label_display }}</strong></p>
      <p class="note">
        Routing score: {{ attempt.routing_score }} (method: {{ attempt.score_method }}).
        This score is an evidence-completeness signal, not a probability of correctness.
        {% if attempt.fallback_observations %}
          Visual fallback evidence is a human-review description, not a machine-verified exact quote.
        {% endif %}
      </p>
      {% if attempt.extraction_status == "COMPLETED" %}
        <h2>Extracted fields</h2>
        <div class="table-wrapper">
          <table>
            <thead>
              <tr><th>Field</th><th>Value</th><th>Status</th><th>Confidence</th><th>Evidence</th></tr>
            </thead>
            <tbody>
              {% for field_name, field in attempt.extraction_result.items %}
                <tr>
                  <td>{{ field_name }}</td>
                  <td>{{ field.value|default:"—" }}</td>
                  <td>{{ field.status }}</td>
                  <td>{{ field.confidence|default:"—" }}</td>
                  <td>{{ field.evidence|default:"—" }}</td>
                </tr>
                {% if field.contradiction_with %}
                  <tr class="warning-row">
                    <td colspan="5">
                      Contradiction: {{ field_name }} matches {{ field.contradiction_with|join:", " }} — needs review.
                    </td>
                  </tr>
                {% endif %}
              {% endfor %}
            </tbody>
          </table>
        </div>
        <p class="note">Field confidence describes extraction-evidence quality, not a probability of correctness.</p>
      {% elif attempt.extraction_status == "UNAVAILABLE" %}
        <p class="note">
          Field extraction technically failed ({{ attempt.extraction_failure_category }}); the
          accepted classification above is unaffected.
        </p>
      {% endif %}
    {% elif attempt.status == "UNCERTAIN" %}
      <p>The document could not be classified with sufficient evidence.</p>
      {% with reason=attempt.fallback_metadata.routing.reason|default:attempt.primary_metadata.routing.reason %}
        {% if reason %}<p class="note">Reason: {{ reason }}</p>{% endif %}
      {% endwith %}
    {% elif attempt.status == "FAILED" %}
      <p>Processing failed at stage <strong>{{ attempt.failure_stage }}</strong> ({{ attempt.failure_category }}).</p>
      <p class="note">{{ attempt.failure_reason }}</p>
    {% else %}
      <p>Still processing.</p>
    {% endif %}

    <p><a href="{% url 'documents:original' pk=attempt.pk %}">View original PDF</a></p>
  </div>
{% endblock %}

